import { describe, it, expect } from 'vitest';
import { evidenceSchema, validateEvidenceFile } from './evidence';

// ============================================================================
// HAPPY PATH TESTS
// ============================================================================

describe('evidenceSchema — happy path', () => {
  it('test_feat_car_003_happy_path_valid_before_evidence_passes', () => {
    const result = evidenceSchema.safeParse({
      evidence_type: 'BEFORE',
      description: 'Photo of damaged fire door before repair',
    });
    expect(result.success).toBe(true);
  });

  it('test_feat_car_003_happy_path_valid_after_evidence_passes', () => {
    const result = evidenceSchema.safeParse({
      evidence_type: 'AFTER',
      description: 'Photo after repair completed',
    });
    expect(result.success).toBe(true);
  });

  it('test_feat_car_003_happy_path_all_evidence_types_pass', () => {
    for (const etype of ['BEFORE', 'AFTER', 'EVIDENCE', 'OTHER'] as const) {
      const result = evidenceSchema.safeParse({
        evidence_type: etype,
        description: 'Valid description text',
      });
      expect(result.success, `type ${etype} should pass`).toBe(true);
    }
  });
});

